 "content": "def transform(grid):
    """Copy the patterned neighborhood of one 5 marker to the other 5 marker."""
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return out

    # The marker embedded in the denser pattern is the source; the isolated 5 is the target.
    def score(pos):
        r, c = pos
        return sum(
            1 for rr in range(max(0, r - 3), min(len(grid), r + 4))
            for cc in range(max(0, c - 3), min(len(grid[0]), c + 4))
            if (rr, cc) != pos and grid[rr][cc] != 0
        )
    source = max(markers, key=score)
    targets = [p for p in markers if p != source]
    sr, sc = source
    pattern = [(r - sr, c - sc, grid[r][c])
               for r, row in enumerate(grid) for c, v in enumerate(row)
               if v != 0 and (r, c) != source]
    for tr, tc in targets:
        for dr, dc, color in pattern:
            rr, cc = tr + dr, tc + dc
            if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
                # Preserve any pre-existing non-background cell.
                if out[rr][cc] == 0:
                    out[rr][cc] = color
    return out
